17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.CustomerCodeGenerator;
33	import org.springframework.samples.petclinic.rest.NamesakeCounter;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
42	import org.springframework.samples.petclinic.rest.validation.DuplicateHouseholdException;
43	import org.springframework.samples.petclinic.rest.validation.DuplicateTelephoneException;
44	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
45	import org.springframework.samples.petclinic.rest.validation.HouseholdDuplicateValidator;
46	import org.springframework.samples.petclinic.rest.validation.HouseholdIdGenerator;
47	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
48	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
49	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    private final OwnerFieldsValidator ownerFieldsValidator;
77	
78	    private final HouseholdDuplicateValidator householdDuplicateValidator;
79	
80	    private final HouseholdIdGenerator householdIdGenerator;
81	
82	    private final TelephoneNormalizer telephoneNormalizer;
83	
84	    private final EmailNormalizer emailNormalizer;
85	
86	    private final AddressNormalizer addressNormalizer;
87	
88	    private final CustomerCodeGenerator customerCodeGenerator;
89	
90	    private final NamesakeCounter namesakeCounter;
91	
92	    public OwnerRestControllerV1(ClinicService clinicService,
93	                                 OwnerMapper ownerMapper,
94	                                 PetMapper petMapper,
95	                                 VisitMapper visitMapper,
96	                                 OwnerFieldsValidator ownerFieldsValidator,
97	                                 HouseholdDuplicateValidator householdDuplicateValidator,
98	                                 HouseholdIdGenerator householdIdGenerator,
99	                                 TelephoneNormalizer telephoneNormalizer,
100	                                 EmailNormalizer emailNormalizer,
101	                                 AddressNormalizer addressNormalizer,
102	                                 CustomerCodeGenerator customerCodeGenerator,
103	                                 NamesakeCounter namesakeCounter) {
104	        this.clinicService = clinicService;
105	        this.ownerMapper = ownerMapper;
106	        this.petMapper = petMapper;
107	        this.visitMapper = visitMapper;
108	        this.ownerFieldsValidator = ownerFieldsValidator;
109	        this.householdDuplicateValidator = householdDuplicateValidator;
110	        this.householdIdGenerator = householdIdGenerator;
111	        this.telephoneNormalizer = telephoneNormalizer;
112	        this.emailNormalizer = emailNormalizer;
113	        this.addressNormalizer = addressNormalizer;
114	        this.customerCodeGenerator = customerCodeGenerator;
115	        this.namesakeCounter = namesakeCounter;
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
121	        Collection<Owner> owners;
122	        if (lastName != null) {
123	            owners = this.clinicService.findOwnerByLastName(lastName);
124	        } else {
125	            owners = this.clinicService.findAllOwners();
126	        }
127	        if (owners.isEmpty()) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
136	        Owner owner = this.clinicService.findOwnerById(ownerId);
137	        if (owner == null) {
138	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
139	        }
140	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
146	        if (ownerFieldsDto != null) {
147	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
148	        }
149	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
150	        if (!missingFields.isEmpty()) {
151	            throw new MissingOwnerFieldsException(missingFields);
152	        }
153	        HttpHeaders headers = new HttpHeaders();
154	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
155	        Collection<Owner> sameLastName =
156	            this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
157	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
158	        applyHouseholdPolicy(owner, ownerFieldsDto, sameLastName);
159	        String normalizedTelephone = telephoneNormalizer.normalize(owner.getTelephone());
160	        if (!this.clinicService.findOwnersByTelephone(normalizedTelephone).isEmpty()) {
161	            throw new DuplicateTelephoneException(normalizedTelephone);
162	        }
163	        owner.setTelephone(normalizedTelephone);
164	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
165	        if (owner.getRegistrationDate() == null) {
166	            owner.setRegistrationDate(LocalDate.now());
167	        }
168	        owner.setCustomerCode(
169	            customerCodeGenerator.generate(owner.getLastName(), clinicService.countOwners()));
170	        this.clinicService.saveOwner(owner);
171	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
172	        headers.setLocation(UriComponentsBuilder.newInstance()
173	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
174	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
175	    }
176	
177	    /**
178	     * Applies the household rule to an owner about to be created. When the owner shares a
179	     * household (same last name and address, compared case-insensitively with collapsed
180	     * whitespace) with an existing owner, creation is rejected unless the request opted in via
181	     * {@code sharesHousehold}. When it opts in, the new owner and every existing household
182	     * member are stamped with the same stable {@code householdId}.
183	     *
184	     * @throws DuplicateHouseholdException if a conflicting owner exists and the caller did not opt in
185	     */
186	    private void applyHouseholdPolicy(Owner owner, OwnerFieldsDto ownerFieldsDto, Collection<Owner> sameLastName) {
187	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
188	        if (members.isEmpty()) {
189	            return;
190	        }
191	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
192	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
193	        }
194	        String householdId = householdIdGenerator.generate(owner);
195	        owner.setHouseholdId(householdId);
196	        for (Owner member : members) {
197	            if (!householdId.equals(member.getHouseholdId())) {
198	                member.setHouseholdId(householdId);
199	                this.clinicService.saveOwner(member);
200	            }
201	        }
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
207	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
208	        if (currentOwner == null) {
209	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	        }
211	        currentOwner.setAddress(ownerFieldsDto.getAddress());
212	        currentOwner.setCity(ownerFieldsDto.getCity());
213	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
214	        currentOwner.setLastName(ownerFieldsDto.getLastName());
215	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
216	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
217	        this.clinicService.saveOwner(currentOwner);
218	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Transactional
223	    @Override
224	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
225	        Owner owner = this.clinicService.findOwnerById(ownerId);
226	        if (owner == null) {
227	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
228	        }
229	        this.clinicService.deleteOwner(owner);
230	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
231	    }
232	
233	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
234	    @Override
235	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
236	        Owner owner = this.clinicService.findOwnerById(ownerId);
237	        if (owner == null) {
238	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
239	        }
240	        HttpHeaders headers = new HttpHeaders();
241	        Pet pet = petMapper.toPet(petFieldsDto);
242	        owner.setId(ownerId);
243	        pet.setOwner(owner);
244	        pet.getType().setName(null);
